import json
import sys
import os
from datetime import datetime

def solve():
    if len(sys.argv) < 3:
        return

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    rule_facts = manifest.get("facts", {})

    # Load usaspending_awards.json
    awards_data = []
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    if os.path.exists(awards_file):
        with open(awards_file, 'r') as f:
            awards_data = json.load(f)

    # Map award_id (generated_unique_award_id) to its data and filename
    award_map = {}
    for award in awards_data:
        uid = award.get("generated_unique_award_id")
        if uid:
            award_map[uid] = award

    results = {}

    for pair in pairs:
        rule_id, entity_id = pair.split("::")
        results[pair] = {}

        # Get the specific award record
        award = award_map.get(entity_id)
        doc_name = os.path.splitext(os.path.basename(awards_file))[0] if award else ""

        # Get facts required for this rule
        facts_to_extract = rule_facts.get(rule_id, [])

        for fact in facts_to_extract:
            val = "ABSENT"
            doc = ""

            if award:
                if fact == "performance start":
                    raw_val = award.get("period_of_performance", {}).get("start_date")
                    if raw_val:
                        try:
                            # Standardize to YYYY-MM-DD
                            dt = datetime.strptime(raw_val[:10], "%Y-%m-%d")
                            val = dt.strftime("%Y-%m-%d")
                            doc = doc_name
                        except ValueError:
                            val = "ABSENT"
                    else:
                        val = "ABSENT"

                elif fact == "performance end":
                    raw_val = award.get("period_of_performance", {}).get("end_date")
                    if raw_val:
                        try:
                            dt = datetime.strptime(raw_val[:10], "%Y-%m-%d")
                            val = dt.strftime("%Y-%m-%d")
                            doc = doc_name
                        except ValueError:
                            val = "ABSENT"
                    else:
                        val = "ABSENT"

                elif fact == "amount obligated":
                    raw_val = award.get("total_obligation")
                    if raw_val is not None:
                        # Format as decimal string
                        val = "{:.2f}".format(float(raw_val))
                        doc = doc_name
                    else:
                        val = "ABSENT"

                elif fact == "potential value":
                    raw_val = award.get("base_and_all_options")
                    if raw_val is not None:
                        val = "{:.2f}".format(float(raw_val))
                        doc = doc_name
                    else:
                        val = "ABSENT"

            if val == "ABSENT":
                results[pair][fact] = "ABSENT"
            else:
                results[pair][fact] = [val, doc]

    print(json.dumps(results))

if __name__ == "__main__":
