import json
import sys
import os

def solve():
    if len(sys.argv) < 3:
        return

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load usaspending_awards.json
    awards_file = os.path.join(packet_dir, 'usaspending_awards.json')
    try:
        with open(awards_file, 'r') as f:
            awards_data = json.load(f)
    except FileNotFoundError:
        print(json.dumps({}))
        return

    # Create a lookup for awards by their generated_unique_award_id
    awards_lookup = {}
    for award in awards_data:
        uid = award.get('generated_unique_award_id')
        if uid:
            awards_lookup[uid] = award

    results = {}

    for pair_str in manifest['pairs']:
        rule_id, entity_id = pair_str.split('::')

        award = awards_lookup.get(entity_id)
        doc_name = "usaspending_awards"

        if rule_id == 'usa.period_3y':
            # Facts: performance start, performance end
            fact_results = {}

            start_val = "ABSENT"
            end_val = "ABSENT"

            if award:
                pop = award.get('period_of_performance', {})
                start_str = pop.get('start_date')
                end_str = pop.get('end_date')

                if start_str:
                    start_val = [start_str, doc_name]
                if end_str:
                    end_val = [end_str, doc_name]

            fact_results['performance start'] = start_val
            fact_results['performance end'] = end_val
            results[pair_str] = fact_results

        elif rule_id == 'usa.obligated_95':
            # Facts: amount obligated, potential value
            fact_results = {}

            amt_obs_val = "ABSENT"
            pot_val_val = "ABSENT"

            if award:
                # amount obligated
                amt = award.get('total_obligation')
                if amt is not None:
                    # Format as decimal string
                    amt_obs_val = [f"{amt:.2f}", doc_name]

                # potential value
                pot = award.get('base_and_all_options')
                if pot is not None:
                    pot_val_val = [f"{pot:.2f}", doc_name]

            fact_results['amount obligated'] = amt_obs_val
            fact_results['potential value'] = pot_val_val
            results[pair_str] = fact_results

    print(json.dumps(results))

if __name__ == "__main__":
    solve()
